/* ---------- captions (burned in, word for word; max 2 lines, bottom edge at y=1272, limit 1280) ---------- */

// [line, firstWord, lastWord] per caption chunk; chunks cover every narrated word once, in order.
// A chunk whose last token ends a sentence (. ? !) disappears when that last word ends; any other chunk stays until the
// next one starts. Every chunk appears when its first word starts (all shifted by CAP_DELAY, below).
export const CHUNKS: [number, number, number][] = [
  [0, 0, 2],
  [0, 3, 6],
  [0, 7, 12],
  [0, 13, 20],
  [1, 0, 3],
  [1, 4, 11],
  [2, 0, 6],
  [2, 7, 10],
  [3, 0, 7],
  [4, 0, 3],
  [4, 4, 11],
  [5, 0, 5],
  [5, 6, 10],
  [6, 0, 5],
  [6, 6, 9],
];
const TOKENS = LINES.map((s) => s.text.split(' '));
// The TTS engine's word boundaries lead the audible onset by about 0.05-0.15s, so captions and the spoken-word
// highlight run 2 frames (0.067s) behind the reported boundaries.
const CAP_DELAY = 2;
const endsSentence = (s: number, b: number) => /[.?!]$/.test(TOKENS[s][b]);
/** [on, off) frame window of caption chunk i. */
export const chunkWindow = (i: number): [number, number] => {
  const [s, a, b] = CHUNKS[i];
  const on = wordF(s, a) + CAP_DELAY;
  const off = endsSentence(s, b) || i === CHUNKS.length - 1 ? wordEndF(s, b) + CAP_DELAY : wordF(CHUNKS[i + 1][0], CHUNKS[i + 1][1]) + CAP_DELAY;
  return [on, off];
};

const Captions: React.FC = () => {
  const f = useCurrentFrame();
  let idx = -1;
  CHUNKS.forEach((_, i) => {
    const [on, off] = chunkWindow(i);
    if (f >= on && f < off) idx = i;
  });
  if (idx < 0) return null;
  const [s, a, b] = CHUNKS[idx];
  const [on] = chunkWindow(idx);
  const t = interpolate(f, [on, on + 3], [0.35, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  return (
    <Layer kind="cap">
      <div style={{position: 'absolute', left: COL_L, width: COL_W, bottom: 1920 - 1272, display: 'flex', justifyContent: 'center', fontFamily: FONT}}>
        <div style={{maxWidth: COL_W, boxSizing: 'border-box', padding: '14px 30px', borderRadius: 36, background: WHITE, border: '3px solid #9FBFEA', boxShadow: '0 4px 10px rgba(26,80,160,0.12)', fontSize: 48, lineHeight: 1.22, fontWeight: 800, textAlign: 'center', opacity: t}}>
          {TOKENS[s].slice(a, b + 1).map((tok, i) => {
            const wi = a + i;
            const started = f >= wordF(s, wi) + CAP_DELAY;
            const nextStart = wi + 1 < LINES[s].words.length ? wordF(s, wi + 1) + CAP_DELAY : Infinity;
            const active = started && f < nextStart;
            return (
              <React.Fragment key={wi}>
                <span style={{color: started ? INK : MUTED, background: active ? ORANGE : 'transparent', borderRadius: 12, padding: '0 4px', margin: '0 -4px', whiteSpace: 'nowrap', display: 'inline-block', lineHeight: 1.1}}>{tok}</span>
                {i < b - a ? ' ' : ''}
              </React.Fragment>
            );
          })}
        </div>
      </div>
    </Layer>
  );
};

/* ---------- verification-only helpers ---------- */

/** Negative control: a saturated box 30px outside one edge of the safe area (or a faint white one: 'violateweak-left'). */
const Violate: React.FC = () => {
  const mode = React.useContext(DebugContext);
  const m = /^violate(weak)?-(left|right|top|bottom)$/.exec(mode);
  if (!m) return null;
  const box: Record<string, React.CSSProperties> = {left: {left: 40, top: 900}, right: {left: 925, top: 900}, top: {left: 500, top: 150}, bottom: {left: 500, top: 1450}};
  return <div style={{position: 'absolute', width: 40, height: 40, backgroundColor: m[1] ? WHITE : '#E5484D', ...box[m[2]]}} />;
};

/** Negative control for the caption-overlap check: the FAINTEST real element of this ad (a white card with its 3px pale-blue
 * border and soft shadow) placed inside the caption zone, content layer only ('nocaps-violatefaint-caption'). */
const FaintViolation: React.FC = () => {
  const mode = React.useContext(DebugContext);
  if (mode !== 'nocaps-violatefaint-caption') return null;
  return <div style={{position: 'absolute', left: 480, top: 1170, width: 120, height: 80, borderRadius: 24, boxSizing: 'border-box', background: WHITE, border: `3px solid ${CARD_BORDER}`, boxShadow: '0 12px 28px rgba(26,80,160,0.16)'}} />;
};

/** Logs every text node's box, colour, size and effective opacity (console line starting AUDIT_JSON). */
const AuditProbe: React.FC = () => {
  const [handle] = useState(() => delayRender('audit'));
  useEffect(() => {
    const out: unknown[] = [];
    document.querySelectorAll('div,span').forEach((el) => {
      el.childNodes.forEach((n) => {
        if (n.nodeType !== 3 || !(n.textContent || '').trim()) return;
        const r = document.createRange();
        r.selectNodeContents(n);
        const b = r.getBoundingClientRect();
        const cs = getComputedStyle(el);
        let op = 1;
        for (let e: Element | null = el; e; e = e.parentElement) op *= parseFloat(getComputedStyle(e).opacity);
        out.push({text: (n.textContent || '').trim(), x0: b.left, y0: b.top, x1: b.right, y1: b.bottom, color: cs.color, size: parseFloat(cs.fontSize), weight: cs.fontWeight, opacity: op});
      });
    });
    console.log('AUDIT_JSON' + JSON.stringify(out));
    continueRender(handle);
  }, [handle]);
  return null;
};

/* ---------- composition ---------- */

export const MegaNetNursesBaySkipAd: React.FC<{debug?: string}> = ({debug = ''}) => {
  const frame = useCurrentFrame();
  return (
    <DebugContext.Provider value={debug}>
      <AbsoluteFill style={{fontFamily: FONT, backgroundColor: '#EAF3FF', filter: debug === 'gray' ? 'grayscale(1)' : undefined}}>
        {debug === 'notext' && <style>{'*{color:transparent!important;-webkit-text-fill-color:transparent!important;text-shadow:none!important}'}</style>}
        <Sequence from={LEAD} layout="none">
          <Audio src={staticFile('voiceover-skip.mp3')} />
        </Sequence>
        {/* everything visual is frozen once the voice has ended: the last 2s are one held frame */}
        <Freeze frame={Math.min(frame, FREEZE)}>
          <Backgrounds />
          <SceneFrame k={0}>{(l) => <Scene1 l={l} />}</SceneFrame>
          <SceneFrame k={1}>{(l) => <Scene2 l={l} />}</SceneFrame>
          <SceneFrame k={2}>{(l) => <Scene3 l={l} />}</SceneFrame>
          <SceneFrame k={3}>{(l) => <Scene4 l={l} />}</SceneFrame>
          <SceneFrame k={4}>{(l) => <Scene5 l={l} />}</SceneFrame>
          <SceneFrame k={5}>{(l) => <Scene6 l={l} />}</SceneFrame>
          <Header />
          <Captions />
          <Violate />
          <CaptionViolation />
          <Layer kind="content">
            <FaintViolation />
          </Layer>
        </Freeze>
        {debug === 'audit' && <AuditProbe />}
      </AbsoluteFill>
    </DebugContext.Provider>
  );
};
